class Animal { void eat() { System.out.println("Eating"); } }
class Dog extends Animal { void bark() { System.out.println("Bark"); } }
public class Main { public static void main(String[] args) { Dog d = new Dog(); d.eat(); d.bark(); } }

class Vehicle { int wheels = 4; }
class Car extends Vehicle { String fuel = "Electric"; }
public class Main { public static void main(String[] args) { Car c = new Car(); System.out.println(c.wheels + ":" + c.fuel); } }

class Base { Base(String label) { System.out.println(label); } }
class Derived extends Base { Derived() { super("Base ready"); } }
public class Main { public static void main(String[] args) { new Derived(); } }

class Shape { int sides() { return 0; } }
class Square extends Shape { int sides() { return 4; } }
public class Main { public static void main(String[] args) { System.out.println(new Square().sides()); } }

class Parent { String type() { return "Parent"; } }
class Child extends Parent { String type() { return super.type() + " Child"; } }
public class Main { public static void main(String[] args) { System.out.println(new Child().type()); } }
